mapper.select:

r.del_flag='0'
  and r.activity_id=#{activityId}
  and r.hotel_id=#{hotelId}
  and r.room_name like concat('%',#{roomName},'%')

order by r.sort_order asc, r.room_id asc

mapper.update:
update yc_hotel_room
hotel_id=#{hotelId}, room_name=#{roomName}, bed_type=#{bedType}, price=#{price}, stock=#{stock}, reserved_stock=#{reservedStock}, sort_order=#{sortOrder}, update_by=#{updateBy}, remark=#{remark}, update_time=sysdate()
where room_id=#{roomId}
